<script setup>
import {computed,onMounted,ref} from 'vue';
import {brewApi} from '../api';
import {IONS,PRESETS,copy} from '../water-chemistry';
import JourneyDetailDialog from './JourneyDetailDialog.vue';
const props=defineProps({initialProductId:[String,Number],initialFactoryId:[String,Number]});
const emit=defineEmits(['changed']);
const data=ref({items:[],products:[],factories:[],can_manage:false,can_manage_common:false}),product=ref(String(props.initialProductId||'')),factory=ref(''),loading=ref(false),saving=ref(false),error=ref(''),formError=ref(''),draft=ref(null),showInactive=ref(false);
const rows=computed(()=>data.value.items.filter(t=>(!product.value||t.product_id===product.value)&&(factory.value==='common'?!t.factory_id:!factory.value||t.factory_id===factory.value)&&(showInactive.value||t.active)));
const range=b=>b?.min==null&&b?.max==null?'未设置':b.min==null?'≤ '+b.max:b.max==null?'≥ '+b.min:b.min+' ～ '+b.max;
async function load(){loading.value=true;error.value='';try{data.value=await brewApi.getWaterTargets();}catch(e){error.value=e.message;}finally{loading.value=false;}}
function edit(target){formError.value='';draft.value=target?copy(target):{product_id:product.value||data.value.products[0]?.id||'',factory_id:data.value.can_manage_common?'':String(props.initialFactoryId||data.value.factories[0]?.id||''),name:'',active:true,is_default:true,notes:'',ions:Object.fromEntries(Object.keys(IONS).map(k=>[k,{min:'',max:''}]))};for(const key of Object.keys(IONS)){draft.value.ions[key]||={min:'',max:''};draft.value.ions[key].min??='';draft.value.ions[key].max??='';}}
function preset(index){draft.value.ions=copy(PRESETS[Number(index)].ions);for(const key of Object.keys(IONS))draft.value.ions[key]||={min:'',max:''};if(!draft.value.name)draft.value.name=PRESETS[Number(index)].name.replace(' · 参考方案',' · 目标方案');}
async function save(){if(saving.value)return;saving.value=true;formError.value='';try{await brewApi.saveWaterTarget(draft.value);draft.value=null;await load();emit('changed');}catch(e){formError.value=e.message;}finally{saving.value=false;}}
onMounted(load);
</script>
<template><section class="water-target-page"><header class="water-target-heading"><div><h2>酒品水质目标</h2><p>按酒品保存目标离子范围。可配置总部通用方案，或指定酒厂的专用方案。</p></div><button v-if="data.can_manage" class="btn btn-primary" type="button" @click="edit()">＋ 新增目标方案</button></header><div class="water-target-filters"><select v-model="product" aria-label="筛选啤酒产品"><option value="">全部酒品</option><option v-for="p in data.products" :key="p.id" :value="p.id">{{ p.name }}</option></select><select v-model="factory" aria-label="筛选目标方案范围"><option value="">全部适用范围</option><option value="common">总部通用</option><option v-for="f in data.factories" :key="f.id" :value="f.id">{{ f.name }}</option></select><label><input v-model="showInactive" type="checkbox">显示已停用</label><button class="btn btn-sm btn-outline" :disabled="loading" @click="load">刷新</button></div><p v-if="error" class="master-error">{{ error }}</p><p v-if="loading" class="empty">正在加载目标方案…</p><div v-else-if="!rows.length" class="water-target-empty"><strong>暂无该酒品的目标水质方案</strong><p>选择酒品，填写六项离子的目标上下限；也可引用参考范围后再调整。</p><button v-if="data.can_manage" class="btn btn-primary" @click="edit()">新增目标方案</button></div><div v-else class="water-target-list"><article v-for="target in rows" :key="target.id" :class="{inactive:!target.active}"><header><div><small>{{ target.product_name }} · {{ target.factory_name }}</small><h3>{{ target.name }}</h3></div><div class="water-target-badges"><span v-if="!target.active">已停用</span><span v-else-if="target.is_default" class="default">默认目标</span><button class="btn btn-sm btn-outline" @click="edit(target)">{{ target.can_edit?'查看 / 修改':'查看详情' }}</button></div></header><dl><div v-for="(label,key) in IONS" :key="key"><dt>{{ label }}</dt><dd>{{ range(target.ions[key]) }} <small>mg/L</small></dd></div></dl><p v-if="target.notes" class="water-target-note">{{ target.notes }}</p></article></div><JourneyDetailDialog v-if="draft" :title="draft.id?'目标水质方案详情':'新增酒品目标方案'" subtitle="设置酿造用水的目标范围；具体添加量由原水、水量和投加方案计算。" @close="!saving&&(draft=null)"><form id="water-target-edit" @submit.prevent="save"><fieldset :disabled="saving||(draft.id?!draft.can_edit:!data.can_manage)" class="water-target-form"><div class="water-target-basics"><label>对应酒品<select v-model="draft.product_id" required :disabled="!!draft.id"><option value="" disabled>选择啤酒产品</option><option v-for="p in data.products" :key="p.id" :value="p.id">{{ p.name }}</option></select></label><label>适用范围<select v-model="draft.factory_id" :disabled="!!draft.id"><option v-if="data.can_manage_common||!draft.factory_id" value="">总部通用 · 全部酒厂</option><option v-for="f in data.factories" :key="f.id" :value="f.id">{{ f.name }}</option></select></label><label class="wide">目标方案名称<input v-model.trim="draft.name" required maxlength="100" placeholder="例如：经典拉格 · 清爽型目标"></label></div><label class="water-target-reference">引用参考范围（可选）<select @change="preset($event.target.value)"><option value="" selected disabled>选择参考模板后调整</option><option v-for="(p,index) in PRESETS" :key="p.name" :value="index">{{ p.name }}</option></select></label><div class="target-range-heading"><h4>目标离子范围</h4><small>单位 mg/L</small></div><div class="target-range-table"><div class="target-range-row heading"><span>离子</span><span>下限</span><span>上限</span></div><div v-for="(label,key) in IONS" :key="key" class="target-range-row"><strong>{{ label }}</strong><input v-model.number="draft.ions[key].min" type="number" min="0" max="100000" step="any" placeholder="不限定" :aria-label="label+'下限'"><input v-model.number="draft.ions[key].max" type="number" min="0" max="100000" step="any" placeholder="不限定" :aria-label="label+'上限'"></div></div><p class="water-target-hint">未设置的指标不参与达标判断。上下限应由酿酒师按酒品确认；参考模板不是统一强制标准。</p><label class="water-target-notes">方案说明<textarea v-model.trim="draft.notes" rows="2" placeholder="记录目标风味、适用工艺或调整说明"></textarea></label><div class="water-target-flags"><label><input v-model="draft.is_default" type="checkbox">设为该酒品在此范围的默认目标</label><label><input v-model="draft.active" type="checkbox">启用</label></div></fieldset><p v-if="formError" class="master-error" role="alert">{{ formError }}</p></form><template #footer><div class="water-target-actions"><button class="btn btn-secondary" :disabled="saving" @click="draft=null">关闭</button><button v-if="draft.id?draft.can_edit:data.can_manage" type="submit" form="water-target-edit" class="btn btn-primary" :disabled="saving">{{ saving?'保存中…':'保存目标方案' }}</button></div></template></JourneyDetailDialog></section></template>
<style scoped>
.water-target-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:24px;margin:16px 0 24px}.water-target-heading h2{font-size:24px;margin:0 0 12px}.water-target-heading p,.water-target-hint{font-size:12px;line-height:1.8;color:var(--text-muted)}.water-target-filters{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-bottom:22px}.water-target-filters select,.water-target-form input:not([type=checkbox]),.water-target-form select,.water-target-form textarea{box-sizing:border-box;width:100%;min-height:44px;height:44px;padding:10px 12px;border:1px solid var(--border-default);border-radius:7px;background:var(--bg-input,#1b1c18);color:var(--text-primary);font:inherit;font-size:13px}.water-target-filters select{width:auto;min-width:180px;max-width:320px}.water-target-filters label{font-size:12px;color:var(--text-muted)}.water-target-list{display:grid;gap:16px}.water-target-list article{padding:22px;border:1px solid var(--border-default);border-radius:11px;background:#ffffff02}.water-target-list article.inactive{opacity:.6}.water-target-list article>header{display:flex;justify-content:space-between;align-items:flex-start;gap:16px}.water-target-list header small{font-size:11px;color:var(--text-muted)}.water-target-list h3{font-size:18px;color:#edcb83;margin:8px 0 0}.water-target-badges{display:flex;align-items:center;gap:12px;flex-shrink:0}.water-target-badges>span{font-size:10px;color:var(--text-muted)}.water-target-badges .default{color:#e0bc70;background:#d4a85314;padding:5px 8px;border:1px solid #d4a85340;border-radius:5px}.water-target-list dl{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:15px;margin:22px 0 0}.water-target-list dt{font-size:11px;color:var(--text-muted);margin-bottom:8px}.water-target-list dd{font-size:17px;margin:0;color:var(--text-primary);font-variant-numeric:tabular-nums}.water-target-list dd small{font-size:10px;color:var(--text-muted)}.water-target-note{font-size:12px;color:var(--text-muted);margin:18px 0 0;line-height:1.8}.water-target-empty{padding:44px 24px;border:1px dashed var(--border-default);border-radius:10px;text-align:center}.water-target-empty p{font-size:12px;color:var(--text-muted);line-height:1.8}.water-target-form{padding:0;margin:0;border:0}.water-target-basics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.water-target-basics label,.water-target-reference,.water-target-notes{display:grid;gap:8px;font-size:12px;color:var(--text-secondary)}.water-target-basics .wide{grid-column:1/-1}.water-target-reference{margin-top:20px}.target-range-heading{display:flex;justify-content:space-between;align-items:center;gap:16px;margin:24px 0 10px}.target-range-heading h4{font-size:14px;margin:0}.target-range-heading small{color:var(--text-muted);font-size:11px}.target-range-row{display:grid;grid-template-columns:minmax(130px,1fr) minmax(85px,1fr) minmax(85px,1fr);align-items:center;gap:16px;padding:11px 0;border-bottom:1px solid var(--border-default)}.target-range-row strong{font-size:12px;font-weight:500}.target-range-row.heading{font-size:11px;color:var(--text-muted)}.water-target-notes{margin-top:20px}.water-target-form textarea{height:auto;min-height:70px}.water-target-flags{display:flex;flex-wrap:wrap;gap:20px;font-size:12px;margin-top:18px}.water-target-actions{display:flex;justify-content:flex-end;align-items:center;gap:12px}@media(max-width:850px){.water-target-list dl{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:550px){.water-target-heading,.water-target-list article>header{flex-direction:column}.water-target-basics{grid-template-columns:1fr}.water-target-basics .wide{grid-column:auto}.water-target-list dl{grid-template-columns:repeat(2,minmax(0,1fr))}.target-range-row{gap:9px;grid-template-columns:minmax(100px,1fr) 85px 85px}.water-target-filters select{width:100%;max-width:none}}
</style>
